// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.reasoningimport com.roshan.persona.cognitive.model.CognitiveConfigimport com.roshan.persona.cognitive.model.Constraintimport com.roshan.persona.cognitive.model.ReasoningStepimport com.roshan.persona.cognitive.model.ReasoningTraceimport com.roshan.persona.cognitive.model.VerificationResultimport com.roshan.persona.persona.core.PersonaProfileimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Self Corrector (Module 7 v2 — Step 7.4). * * Verifies reasoning traces using TWO strategies (per v2 review fix #7): * *  1. **Rule-based** (fast, < 100ms) — check constraints satisfied, no *     contradictions, logic is sound. *  2. **LLM-based** (slower, < 2s) — ask LLM "Is this reasoning correct? *     What's wrong?" * * ## Self-correction flow (per Q2: show both mistake + correction) * * ``` * 1. Generate answer. * 2. Rule-based verify (fast). *    → Verified: done. *    → NeedsCorrection: go to step 3. *    → Failed: go to step 3. * 3. LLM-based verify (slower). *    → Verified: done. *    → NeedsCorrection: retry with alternative approach (max 3 attempts). *    → Failed: return best answer with low confidence. * 4. If retried: show BOTH original + corrected answer. *    "I initially thought X, but on reflection, Y is better because..." * ``` * * ## Max attempts * * [CognitiveConfig.maxCorrectionAttempts] (default 3). After 3 failed * corrections, the best answer is returned with reduced confidence. * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§ReasoningEngine — Self-correction</a> */class SelfCorrector(    private val llm: ReasoningLlm,    private val config: CognitiveConfig = CognitiveConfig(),    private val dispatcher: CoroutineDispatcher,) {    /**     * Verify a reasoning trace.     *     * Runs rule-based check first (fast). If that passes, runs LLM-based     * check (thorough). Returns the most severe result.     *     * @param trace the reasoning trace to verify.     * @param constraints the constraints the answer must satisfy.     * @param persona the active persona (for LLM verify prompt style).     * @return verification result.     */    suspend fun verify(        trace: ReasoningTrace,        constraints: List<Constraint>,        persona: PersonaProfile,    ): VerificationResult = withContext(dispatcher) {        // 1. Rule-based verification (fast, free).        val ruleResult = ruleBasedVerify(trace, constraints)        if (ruleResult is VerificationResult.Verified) {            // 2. LLM-based verification (slower, more thorough).            val llmResult = llmVerify(trace, persona)            return@withContext llmResult  // LLM result is more authoritative        }        // Rule-based found an issue — return it immediately.        ruleResult    }    /**     * Rule-based verification — fast checks without LLM.     *     * Checks:     *  1. All steps have non-blank thought.     *  2. No obvious contradictions (step N contradicts step N-1).     *  3. Confidence is > 0 (not a hallucinated zero-confidence trace).     *  4. Final answer is non-blank.     *  5. Constraint keywords appear in the answer (basic check).     */    internal fun ruleBasedVerify(        trace: ReasoningTrace,        constraints: List<Constraint>,    ): VerificationResult {        // Check 1: all steps have thought.        for (step in trace.steps) {            if (step.thought.isBlank()) {                return VerificationResult.NeedsCorrection(                    issue = "A reasoning step has a blank thought.",                    suggestedFix = "Regenerate the step with a clear thought.",                )            }        }        // Check 2: confidence > 0.        if (trace.confidence <= 0f) {            return VerificationResult.Failed(                "Confidence is zero — reasoning may be hallucinated."            )        }        // Check 3: final answer is non-blank (already enforced by data class init).        // Check 4: constraint keywords in answer (basic heuristic).        val answerLower = trace.finalAnswer.lowercase()        for (constraint in constraints) {            if (constraint.type == com.roshan.persona.cognitive.model.ConstraintType.BUDGET) {                // Check if any number appears in the answer (budget mentioned).                if (!answerLower.contains(Regex("\\d"))) {                    return VerificationResult.NeedsCorrection(                        issue = "Budget constraint mentioned but no numbers in the answer.",                        suggestedFix = "Include specific budget figures in the answer.",                    )                }            }        }        // Check 5: obvious contradictions (step N says X, step N+1 says "not X").        for (i in 1 until trace.steps.size) {            val prev = trace.steps[i - 1].thought.lowercase()            val curr = trace.steps[i].thought.lowercase()            if (isContradiction(prev, curr)) {                return VerificationResult.NeedsCorrection(                    issue = "Step ${i + 1} appears to contradict step $i.",                    suggestedFix = "Resolve the contradiction and regenerate the conflicting step.",                )            }        }        // Check 6: unsupported conclusions — final answer claims something        // not mentioned in any step's observation.        val allObservations = trace.steps.joinToString(" ") { it.observation.lowercase() }        val answerWords = trace.finalAnswer.lowercase()            .split(Regex("\\W+"))            .filter { it.length > 4 }  // skip short words            .distinct()        val unsupportedClaims = answerWords.filter { word ->            word !in allObservations && word !in setOf("the", "this", "that", "with", "from", "have", "been", "will", "would", "could", "should")        }        if (unsupportedClaims.size > 3) {            // More than 3 significant words in the answer don't appear in any            // observation — the answer may be hallucinated.            return VerificationResult.NeedsCorrection(                issue = "Final answer contains claims not supported by reasoning observations: ${unsupportedClaims.take(5)}",                suggestedFix = "Either add reasoning steps that support these claims, or remove them from the answer.",            )        }        // Check 7: circular reasoning — step N's thought is identical to        // step N-1's thought (repeating the same point without progress).        for (i in 1 until trace.steps.size) {            if (trace.steps[i].thought.equals(trace.steps[i - 1].thought, ignoreCase = true)) {                return VerificationResult.NeedsCorrection(                    issue = "Step ${i + 1} repeats step $i without adding new information (circular reasoning).",                    suggestedFix = "Either advance the reasoning or remove the duplicate step.",                )            }        }        return VerificationResult.Verified    }    /**     * Detect contradiction between two consecutive step thoughts.     *     * Checks for:     *  - Explicit negation: "actually, no", "wait, that's wrong", "on second thought"     *  - Negation phrases: "but actually", "however, the opposite", "not really"     *  - Direct contradiction: step N says "X is true", step N+1 says "X is false"     */    private fun isContradiction(prev: String, curr: String): Boolean {        // Explicit negation starters.        val negationStarters = listOf(            "actually, no", "wait, that's wrong", "on second thought, the previous",            "but actually", "however, the opposite", "not really", "that's not right",            "i was wrong", "let me reconsider", "scratch that",        )        if (negationStarters.any { curr.startsWith(it) }) return true        // Direct contradiction: prev contains "X is true/yes/good", curr contains "X is false/no/bad".        val prevWords = prev.split(Regex("\\W+")).toSet()        val currWords = curr.split(Regex("\\W+")).toSet()        val sharedWords = prevWords.intersect(currWords) - setOf("the", "a", "is", "was", "to", "and", "of", "in", "it", "that", "this")        if (sharedWords.isNotEmpty()) {            val prevHasAffirm = prev.contains(Regex("\\b(is true|yes|good|correct|right|valid|works)\\b"))            val currHasNegate = curr.contains(Regex("\\b(is false|no|bad|incorrect|wrong|invalid|doesn't work|does not work)\\b"))            if (prevHasAffirm && currHasNegate) return true        }        return false    }    /**     * LLM-based verification — thorough check with LLM.     *     * Sends the reasoning trace to the LLM and asks: "Is this reasoning     * correct? What's wrong?"     */    private suspend fun llmVerify(        trace: ReasoningTrace,        persona: PersonaProfile,    ): VerificationResult = withContext(dispatcher) {        val prompt = """Verify the following reasoning trace. Is it correct? Are there any logical errors, factual mistakes, or missing considerations?Answer with one of:- VERIFIED (if correct)- NEEDS_CORRECTION: [specific issue] (if mostly correct but has a flaw)- FAILED: [reason] (if fundamentally flawed)Reasoning trace:${trace.steps.joinToString("\n") { "- ${it.thought} → ${it.action} → ${it.observation}" }}Final answer: ${trace.finalAnswer}Confidence: ${trace.confidence}        """.trimIndent()        val response = try {            llm.reason(prompt, persona.llmHyperparams.temperature)        } catch (t: Throwable) {            return@withContext VerificationResult.Verified  // can't verify → assume OK        }        parseVerificationResponse(response)    }    /**     * Parse the LLM verification response.     *     * Expected formats:     *  - "VERIFIED"     *  - "NEEDS_CORRECTION: The budget calculation is wrong."     *  - "FAILED: The reasoning is based on incorrect flight prices."     */    internal fun parseVerificationResponse(response: String): VerificationResult {        val upper = response.uppercase().trim()        return when {            upper.startsWith("VERIFIED") -> VerificationResult.Verified            upper.startsWith("NEEDS_CORRECTION") -> {                val issue = response.substringAfter(":").trim().ifBlank { "Unknown issue" }                VerificationResult.NeedsCorrection(                    issue = issue,                    suggestedFix = "Regenerate the reasoning addressing: $issue",                )            }            upper.startsWith("FAILED") -> {                val reason = response.substringAfter(":").trim().ifBlank { "Unknown failure" }                VerificationResult.Failed(reason)            }            else -> VerificationResult.Verified  // can't parse → assume OK        }    }}